fn swap_first_last(mut q: Queue) -> Queue {
    if let Some(first) = get(q.items, 0) {
        if let Some(last_index) = len(q.items).checked_sub(1) {
            if let Some(last) = get(q.items, last_index) {
                std::mem::swap(&mut q.items[0], &mut q.items[last_index]);
            }
        }
    }
    q
}

